/*!50003 CREATE*/ /*!50017 DEFINER=`Diego.Garrido`@`%`*/ /*!50003 TRIGGER `trg_tb_products_after_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        record_id,
        table_operation,
        db_user,
        table_description
    )
    VALUES (
        'tb_products',
        NEW.ID,
        'Create',
        USER(),
        CONCAT(
            'Producto creado: "',
            NEW.name,
            '". SKU: ',
            NEW.SKU,
            ', Precio: $',
            NEW.current_price,
            ', Stock inicial: ',
            NEW.current_stock
        )
    );
END */;;
